// ❌ OLD: synchronized has no timeout or interruptible wait. If the
// lock holder hangs, every waiter blocks indefinitely — a classic
// production incident (threads pile up, thread pool exhausts).
public class LockingBad {
  private final Object lock = new Object();

  public void doWork() {
    synchronized (lock) { // ❌ OLD: unbounded wait
      // ... critical section
    }
  }

  // No way to say 'wait at most 2 seconds' or to interrupt a waiter
  // that's stuck on the monitor — the only escape is a thread dump and
  // a restart.

import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

// ✅ NEW: tryLock gives a bounded wait (timeout) and is interruptible.
// Must release in finally — the lock does NOT auto-release.
public class LockingGood {
  private final ReentrantLock lock = new ReentrantLock();

  public boolean doWork() {
    try {
      // ✅ NEW: bounded wait — fails fast after 2s instead of blocking
      if (!lock.tryLock(2, TimeUnit.SECONDS)) {
        return false; // ✅ NEW: handle 'couldn't get the lock' gracefully
      }
      try {
        // ... critical section
        return true;
      } finally {
        lock.unlock(); // ✅ NEW: manual release, guaranteed by finally
      }
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt(); // restore the flag
      return false;
    }
  }
}

// Also available: lock.lockInterruptibly(), fair = true, and
// lock.newCondition() for await/signal with multiple queues.
